cd /tmp/wt/chandler && python3 - <<'EOF'
import subprocess, re
REPO='/tmp/wt/chandler'
cache={}
def epfile(path):
    if path not in cache:
        r=subprocess.run(['git','show',f'origin/main:{path}'],capture_output=True,text=True,cwd=REPO)
        cache[path]=r.stdout if r.returncode==0 else None
    return cache[path]
tot=0; ok=0; probs=[]
for b in ['chandler','monica','rachel','joey','phoebe','ross']:
    shas=subprocess.run(['git','log','--format=%H','origin/friend/'+b],capture_output=True,text=True,cwd=REPO).stdout.split()
    for sha in shas:
        body=subprocess.run(['git','show','-s','--format=%B',sha],capture_output=True,text=True,cwd=REPO).stdout
        if 'Friend-Message: 1' not in body: continue
        tot+=1
        m=re.search(r'^Episode: S(\d+)/E(\d+)',body,re.M)
        u=re.search(r'Reply-To:.*?\n\n(.*)',body,re.S)
        if not m or not u:
            probs.append((b,sha[:8],'unparsed','')); continue
        path=f"S{int(m.group(1)):02d}/E{int(m.group(2)):02d}.md"
        txt=epfile(path)
        utt=u.group(1).strip()
        if txt is None: probs.append((b,sha[:8],path+' MISSING',utt[:50]))
        elif utt in txt: ok+=1
        else: probs.append((b,sha[:8],path+' NOTFOUND',utt[:70]))
print(f"total msg commits={tot} verbatim={ok} problems={len(probs)}")
for p in probs[:25]: print(p)
EOF
